El conocimiento inyectado (agentes de IA) **no tiene nada que ver** con tests de una calculadora. Pero esto lo sé de base, sin necesidad de investigar.

---

Acá tenés una suite de tests completa para una calculadora usando `pytest`. Asumo una clase `Calculator` con operaciones básicas:

```python
# calculator.py
class Calculator:
    def add(self, a, b):
        return a + b

    def subtract(self, a, b):
        return a - b

    def multiply(self, a, b):
        return a * b

    def divide(self, a, b):
        if b == 0:
            raise ValueError("No se puede dividir por cero")
        return a / b

    def power(self, a, b):
        return a ** b

    def modulo(self, a, b):
        if b == 0:
            raise ValueError("No se puede calcular módulo con cero")
        return a % b
```

```python
# test_calculator.py
import pytest
from calculator import Calculator

@pytest.fixture
def calc():
    """Fixture que provee una instancia limpia de Calculator"""
    return Calculator()

# --- ADD ---

class TestAdd:
    def test_add_positivos(self, calc):
        assert calc.add(2, 3) == 5

    def test_add_negativos(self, calc):
        assert calc.add(-1, -1) == -2

    def test_add_mixto(self, calc):
        assert calc.add(-5, 10) == 5

    def test_add_cero(self, calc):
        assert calc.add(0, 7) == 7
        assert calc.add(7, 0) == 7

    def test_add_flotantes(self, calc):
        assert calc.add(2.5, 3.1) == pytest.approx(5.6)

    def test_add_grandes(self, calc):
        assert calc.add(1_000_000, 2_000_000) == 3_000_000

# --- SUBTRACT ---

class TestSubtract:
    def test_subtract_basico(self, calc):
        assert calc.subtract(10, 4) == 6

    def test_subtract_negativo(self, calc):
        assert calc.subtract(3, 10) == -7

    def test_subtract_cero(self, calc):
        assert calc.subtract(5, 0) == 5
        assert calc.subtract(0, 5) == -5

    def test_subtract_flotantes(self, calc):
        assert calc.subtract(10.5, 0.5) == pytest.approx(10.0)

# --- MULTIPLY ---

class TestMultiply:
    def test_multiply_positivos(self, calc):
        assert calc.multiply(4, 5) == 20

    def test_multiply_por_cero(self, calc):
        assert calc.multiply(100, 0) == 0
        assert calc.multiply(0, 100) == 0

    def test_multiply_negativos(self, calc):
        assert calc.multiply(-3, 4) == -12
        assert calc.multiply(-3, -4) == 12

    def test_multiply_flotantes(self, calc):
        assert calc.multiply(2.5, 2) == pytest.approx(5.0)

# --- DIVIDE ---

class TestDivide:
    def test_divide_exacta(self, calc):
        assert calc.divide(10, 2) == 5.0

    def test_divide_no_exacta(self, calc):
        assert calc.divide(7, 2) == 3.5

    def test_divide_por_uno(self, calc):
        assert calc.divide(42, 1) == 42.0

    def test_divide_negativos(self, calc):
        assert calc.divide(-10, 2) == -5.0
        assert calc.divide(10, -2) == -5.0
        assert calc.divide(-10, -2) == 5.0

    def test_divide_por_cero(self, calc):
        with pytest.raises(ValueError, match="No se puede dividir por cero"):
            calc.divide(10, 0)

    def test_divide_cero(self, calc):
        assert calc.divide(0, 5) == 0.0

    def test_divide_flotantes(self, calc):
        assert calc.divide(5.0, 2.0) == pytest.approx(2.5)

# --- POWER ---

class TestPower:
    def test_power_cuadrado(self, calc):
        assert calc.power(3, 2) == 9

    def test_power_cubo(self, calc):
        assert calc.power(2, 3) == 8

    def test_power_exponente_cero(self, calc):
        assert calc.power(5, 0) == 1

    def test_power_exponente_uno(self, calc):
        assert calc.power(7, 1) == 7

    def test_power_negativo(self, calc):
        assert calc.power(2, -1) == pytest.approx(0.5)

    def test_power_base_negativa(self, calc):
        assert calc.power(-2, 3) == -8

# --- MODULO ---

class TestModulo:
    def test_modulo_basico(self, calc):
        assert calc.modulo(10, 3) == 1

    def test_modulo_divisible(self, calc):
        assert calc.modulo(9, 3) == 0

    def test_modulo_por_cero(self, calc):
        with pytest.raises(ValueError, match="No se puede calcular módulo con cero"):
            calc.modulo(10, 0)

    def test_modulo_negativos(self, calc):
        # Python: resultado conserva signo del divisor
        assert calc.modulo(-10, 3) == 2  # porque -10 = -4*3 + 2

# --- PROPIEDADES / CASOS ESQUINA ---

class TestPropiedades:
    """Tests basados en propiedades matemáticas"""

    def test_add_identidad(self, calc):
        import random
        for _ in range(10):
            n = random.randint(-100, 100)
            assert calc.add(n, 0) == n

    def test_add_conmutativa(self, calc):
        import random
        for _ in range(10):
            a, b = random.randint(-50, 50), random.randint(-50, 50)
            assert calc.add(a, b) == calc.add(b, a)

    def test_multiply_conmutativa(self, calc):
        import random
        for _ in range(10):
            a, b = random.randint(-20, 20), random.randint(-20, 20)
            assert calc.multiply(a, b) == calc.multiply(b, a)

    def test_subtract_inverso_add(self, calc):
        assert calc.subtract(calc.add(10, 5), 5) == 10

# --- TIPOS ---

class TestTipos:
    def test_divide_devuelve_float(self, calc):
        resultado = calc.divide(4, 2)
        assert isinstance(resultado, float)

    def test_add_enteros_devuelve_entero(self, calc):
        resultado = calc.add(3, 5)
        assert isinstance(resultado, int) and not isinstance(resultado, bool)
```

**Para correr los tests:**

```bash
pytest test_calculator.py -v
```

O si querés cobertura:

```bash
pytest test_calculator.py -v --cov=calculator
```

**Lo que cubre la suite:**

| Aspecto | Qué testea |
|---|---|
| **Operaciones básicas** | add, subtract, multiply, divide, power, modulo |
| **Casos límite** | cero, uno, negativos, flotantes |
| **Errores esperados** | división por cero, módulo por cero |
| **Propiedades** | conmutatividad, identidad, inversos |
| **Aleatoriedad** | tests con datos aleatorios para cubrir más casos |
| **Tipos de retorno** | que divide devuelve float, que sumar enteros devuelve int |
| **Aproximación** | `pytest.approx` para flotantes (evita falsos positivos por precisión) |

Si la calculadora tuviera más operaciones (raíz, logaritmo, trigonometría) o si no es una clase sino funciones sueltas, decime y ajusto los tests.
